const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16m-6-6 6 6-6 6',work:'M8 6V3h8v3M3 6h18v14H3zM3 11h18M10 11v3h4v-3',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16',shield:'M12 2l9 4v7c-1 5-5 7-9 9-4-2-8-4-9-9V6zM8 12l3 3 5-6',leaf:'M20 3C4 2 1 10 5 16c4 6 16 2 15-13M3 21 15 9',users:'M16 21v-3c0-3-3-5-7-5s-7 2-7 5v3M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0M17 3c5 0 5 7 0 7M18 13c4 1 4 4 4 8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',file:'M4 2h11l5 5v15H4zM14 2v6h6M8 12h8M8 16h8',plus:'M12 4v16M4 12h16',mail:'M2 4h20v16H2zM2 5l10 8L22 5',calendar:'M3 5h18v16H3zM7 2v6M17 2v6M3 10h18',external:'M14 3h7v7M21 3 10 14M10 3H3v18h18v-7'};
const icon=(n='arrow')=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.arrow}"/></svg>`;
let data=[],requests=[],studioTab='dashboard',editing=null,filter='Tutti',query='',page=1,studioFilter='all';
const categories=['Tutti','Bandi e opportunità','Lavoro e welfare','ANIEM Lazio','Mercati esteri','Vita associativa'];
const categoryLabel=c=>c==='Edilizia e ANIEM'?'ANIEM Lazio':c;
const date=d=>d?new Date(d+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'long',year:'numeric'}):'Focus associativo';
const shortDate=d=>d?new Date(d+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'short',year:'numeric'}):'Servizi alle imprese';
const published=()=>data.filter(x=>x.status==='published');
const safeURL=u=>/^https:\/\//.test(u||'')?esc(u):'#';
const articleLink=a=>'/notizie/'+encodeURIComponent(a.id);
let serviceList=[['lavoro','Relazioni sindacali','Contratti, assistenza e welfare per le persone della tua impresa.','users'],['credito','Credito e finanza','Orientamento tra credito, fisco e opportunità di finanziamento.','work'],['formazione','Formazione','Competenze e percorsi di crescita per le imprese e i lavoratori.','book'],['estero','Internazionalizzazione','Progetti e accompagnamento verso i mercati esteri.','globe'],['sicurezza','Sicurezza e qualità','Un riferimento per la sicurezza e la qualità in azienda.','shield'],['ambiente','Ambiente e territorio','Assistenza sui temi ambientali e lo sviluppo del territorio.','leaf']];
function header(active='') {return `<header><div class="utility"><div class="wrap"><span>CONFAPI ROMA E LAZIO · AL FIANCO DELLE PMI</span><div class="utility-links"><a href="/sistema-confapi">Il sistema CONFAPI</a><a href="/contatti">Contatti</a><a href="/admin">Area redazione ${icon('external')}</a></div></div></div><div class="wrap masthead"><a href="/" class="identity" aria-label="CONFAPI Roma, homepage"><img class="logo" src="/assets/logos/logo-confapi_1000.png" alt="CONFAPI Roma — Associazione delle piccole e medie imprese"><span class="brand-note">La voce delle imprese.<br>La forza del territorio.</span></a><div class="head-actions"><a class="button" href="/associarsi">Diventa associato ${icon()}</a></div></div><div class="nav-shell"><nav class="wrap nav" aria-label="Navigazione principale"><button type="button" class="menu-toggle" aria-expanded="false" aria-controls="primary-links"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg><span>Menu</span></button><div class="nav-links" id="primary-links">${[['/','Home'],['/notizie','News'],['/aniem','News Aniem'],['/servizi','Servizi alle imprese'],['/chi-siamo','L’associazione'],['/sistema-confapi','Sistema CONFAPI'],['/convenzioni','Convenzioni'],['/contatti','Contatti']].map(([url,label])=>url==='/sistema-confapi'?systemMenu(active):url==='/servizi'?`<div class="services-nav"><div class="services-nav-heading"><a href="/servizi" class="${active===label?'active':''}">${label}</a><button type="button" class="services-toggle" aria-expanded="false" aria-controls="service-submenu" aria-label="Mostra i servizi"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg></button></div><div class="service-submenu" id="service-submenu">${serviceList.map(([id,title,desc,ic])=>`<a href="/servizi/${id}">${icon(ic)}<span><strong>${title}</strong><small>${desc}</small></span></a>`).join('')}</div></div>`:`<a href="${url}" class="${active===label?'active':''}" ${active===label?'aria-current="page"':''}>${label}</a>`).join('')}</div><a href="/notizie?ricerca=1" class="search-button" aria-label="Cerca nel sito">${icon('search')}<span>Cerca</span></a></nav></div></header>`;}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="footer-logo" href="/" aria-label="CONFAPI Roma, homepage"><img src="/assets/logos/logo-confapi_1000.png" alt="CONFAPI Roma" width="320" height="64"></a><p>Rappresentanza, servizi e opportunità per le piccole e medie imprese di Roma e del Lazio.</p><a href="/associarsi">Costruiamo insieme la tua prossima opportunità →</a></div><div><h3>L’associazione</h3><a href="/chi-siamo">Chi siamo</a><a href="/chi-siamo#governance">Governance</a><a href="/assets/docs/atto-costitutivo_e_statuto_confapi_roma.pdf" target="_blank" rel="noopener">Statuto</a></div><div><h3>Per la tua impresa</h3><a href="/servizi">Servizi</a><a href="/notizie">Notizie e circolari</a><a href="/convenzioni">Convenzioni</a><a href="/associarsi">Come associarsi</a></div><div><h3>Restiamo in contatto</h3><a href="/contatti">Scrivi all’associazione</a><a href="tel:+393337774975">333 7774975</a><a href="/admin">Area redazione</a></div></div><div class="footer-bottom"><span>© 2026 CONFAPI Roma e Lazio · Proposta di redesign</span><span><a href="https://www.confapiroma.it/index.php/privacy" target="_blank" rel="noopener">Privacy</a> &nbsp; · &nbsp; <a href="/analisi">Analisi e progetto</a> &nbsp; · &nbsp; Demo locale</span></div></div></footer>`;}
function trend(){const latest=published().slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,10);return `<section class="wrap news-ticker" aria-label="Ultime pubblicazioni"><div class="ticker-window" tabindex="0" aria-label="Scorri le ultime dieci pubblicazioni"><div class="ticker-track">${latest.map(a=>`<a href="${articleLink(a)}"><span>${esc(categoryLabel(a.category))}</span><time datetime="${esc(a.date||'')}">${a.date?shortDate(a.date):'Data non disponibile'}</time><strong>${esc(a.title)}</strong></a>`).join('')}</div></div></section>`;}
function card(a){return `<article class="news-card"><a href="${articleLink(a)}"><img src="${esc(a.image)}" alt="" loading="lazy"><div class="eyebrow">${esc(categoryLabel(a.category))}</div><h3>${esc(a.title)}</h3></a><p>${esc(a.summary)}</p><div class="meta"><span>${shortDate(a.date)}</span><span>·</span><span>${esc(a.type)}</span></div></article>`;}
function serviceGrid(){return `<div class="service-grid">${serviceList.map(([id,title,desc,ic])=>`<a href="/servizi/${id}" class="service-item">${icon(ic)}<div><h3>${title}</h3><p>${desc}</p></div><span>↗</span></a>`).join('')}</div>`;}
function home(){const items=published();const lead=items.find(x=>x.featured)||items.find(x=>x.id==='bando-pmi-lazio')||items[0];if(!lead)return `${header('Home')}<main id="main" class="wrap page-title"><h1>CONFAPI Roma</h1><p>Le prossime notizie saranno disponibili qui.</p></main>${footer()}`;const side=['aniem-4-settembre','rinnovi-contrattuali','progetto-usa'].map(id=>items.find(x=>x.id===id)).filter(Boolean);return `${header('Home')}${trend()}<main id="main"><div class="wrap"><div class="edition"><span class="eyebrow">Il punto sulle imprese</span><time>Mercoledì 9 settembre 2026</time></div><section class="front-grid" aria-label="In primo piano"><a href="${articleLink(lead)}" class="hero-story"><img src="${esc(lead.image)}" alt="Lavorazione industriale, dal patrimonio fotografico CONFAPI" fetchpriority="high"><div class="hero-text"><span class="tag">${esc(lead.category)}</span><h1>${esc(lead.title)}</h1><p>${esc(lead.summary)}</p><div class="hero-bottom"><span>CONFAPI ROMA &nbsp; · &nbsp; ${shortDate(lead.date)}</span><span class="circle-arrow">↗</span></div></div></a><div class="side-stories">${side.map(a=>`<article class="side-story"><div><div class="eyebrow">${esc(categoryLabel(a.category))}</div><a href="${articleLink(a)}"><h3>${esc(a.title)}</h3></a><div class="meta">${shortDate(a.date)} <span>· ${esc(a.type)}</span></div></div><a href="${articleLink(a)}" tabindex="-1" aria-hidden="true"><img src="${esc(a.image)}" alt=""></a></article>`).join('')}</div></section><div class="quick-strip"><div class="quick-intro">Di cosa ha bisogno<br>la tua impresa?<span>Un accesso diretto alle opportunità.</span></div><a class="quick-item" href="/notizie?categoria=Bandi%20e%20opportunit%C3%A0"><span><strong>Bandi e finanziamenti</strong><small>Trova le opportunità per investire e crescere.</small></span>${icon()}</a><a class="quick-item" href="/servizi/lavoro"><span><strong>Assistenza e contratti</strong><small>Un supporto nelle relazioni di lavoro.</small></span>${icon()}</a><a class="quick-item" href="/associarsi"><span><strong>Entrare in CONFAPI</strong><small>Scopri i servizi e come associarti.</small></span>${icon()}</a></div><section><div class="section-top"><div><div class="eyebrow">Informarsi per crescere</div><h2>Notizie, idee, opportunità.</h2></div><a class="text-link" href="/notizie">Tutte le pubblicazioni ↗</a></div><div class="tabs" aria-label="Filtra le notizie">${categories.slice(0,5).map(c=>`<button class="tab ${filter===c?'active':''}" data-home-filter="${esc(c)}">${c==='Tutti'?'Tutte le notizie':categoryLabel(c)}</button>`).join('')}</div><div class="news-grid" id="home-news">${homeCards()}</div></section></div><section class="soft-section section-space"><div class="wrap service-layout"><div class="service-intro"><div class="eyebrow">Competenze che fanno la differenza</div><h2>Ogni impresa è unica.<br>Il supporto, concreto.</h2><p>Affianchiamo le piccole e medie imprese nelle decisioni di ogni giorno. Dalle persone ai mercati, un sistema di competenze al tuo fianco.</p><a href="/servizi" class="text-link">Scopri tutti i servizi ↗</a></div>${serviceGrid()}</div></section><section class="wrap section-space split-feature"><div class="aniem-feature"><div><span class="eyebrow">ANIEM LAZIO</span><h2>Il territorio si costruisce. Insieme.</h2><p>Appalti, aggiornamenti e rappresentanza per le imprese dell’edilizia. Un punto di riferimento dedicato al settore.</p></div><img src="/assets/editorial/territorio.jpg" alt="Territorio e sistema produttivo" loading="lazy"></div><div class="agenda"><div class="section-top"><h2>Scadenze e pubblicazioni</h2>${icon('calendar')}</div><a class="agenda-row" href="/notizie/bando-pmi-lazio"><div class="date-box">28<small>SET 2026</small></div><div><span class="eyebrow">Scadenza bando</span><h3>PMI nelle aree del cratere sismico</h3><p>Termine per la presentazione delle domande</p></div></a><a class="agenda-row" href="/notizie/aniem-4-settembre"><div class="date-box">04<small>SET 2026</small></div><div><span class="eyebrow">Pubblicazione</span><h3>Il nuovo periodico ANIEM</h3><p>Consulta l’ultima edizione disponibile</p></div></a><a class="text-link" href="/notizie">Vai all’archivio delle pubblicazioni ↗</a></div></section><div class="wrap"><section class="newsletter"><div><div class="eyebrow">Un filo diretto con CONFAPI</div><h2>Le informazioni giuste. Le persone giuste.</h2><p>Parliamo delle esigenze della tua impresa e delle opportunità per crescere.</p></div><a class="button" href="/contatti">Entra in contatto ${icon('mail')}</a></section>${networkSection()}</div></main>${footer()}`;}
function homeCards(){const a=published().filter(x=>!x.needsReview&&x.id!=='bando-pmi-lazio'&&(filter==='Tutti'||x.category===filter));return a.length?a.slice(0,3).map(card).join(''):`<div class="empty">Le pubblicazioni di questa area sono consultabili nell’archivio.<br><a class="text-link" href="/notizie?categoria=${encodeURIComponent(filter)}">Apri l’archivio →</a></div>`;}
function news(){const params=new URLSearchParams(location.search);filter=categoryLabel(params.get('categoria')||'Tutti');query=params.get('q')||'';page=1;return `${header('News')}<main class="wrap" id="main"><div class="page-title"><div class="eyebrow">Il magazine delle imprese</div><h1>Il valore di essere informati.</h1><p>Notizie, circolari, bandi e approfondimenti. Tutto ciò che serve alla tua impresa, organizzato per argomento.</p></div><div class="search-row"><label class="visually-hidden" for="news-search">Cerca nell’archivio</label><input id="news-search" class="search-field" type="search" placeholder="Cerca un argomento, un servizio, una parola chiave…" value="${esc(query)}"><select class="search-field" id="news-sort" aria-label="Ordine delle pubblicazioni"><option value="new">Più recenti</option><option value="old">Meno recenti</option></select></div><div class="tabs">${categories.map(c=>`<button class="tab ${filter===c?'active':''}" data-news-filter="${esc(c)}">${c}</button>`).join('')}</div><div id="archive-result"></div></main>${footer()}`;}
function renderArchive(){let a=published().filter(x=>(filter==='Tutti'||x.category===filter)&&(!query||`${x.title} ${x.summary} ${x.category}`.toLowerCase().includes(query.toLowerCase())));const direction=$('#news-sort')?.value==='old'?1:-1;a.sort((x,y)=>direction*((x.date||'0000').localeCompare(y.date||'0000')));const total=a.length;const pages=Math.max(1,Math.ceil(total/9));page=Math.min(page,pages);$('#archive-result').innerHTML=`<p class="count">${total} pubblicazioni ${filter!=='Tutti'?'· '+esc(filter):''}</p><div class="news-grid">${a.slice((page-1)*9,page*9).map(card).join('')||'<div class="empty"><h3>Nessun risultato trovato</h3><p>Prova una parola diversa o seleziona un’altra categoria.</p><button class="button light" data-reset-search>Mostra tutte le pubblicazioni</button></div>'}</div><div class="pagination"><button class="button light" data-page="${page-1}" ${page===1?'disabled':''}>← Precedenti</button><span>${page} / ${pages}</span><button class="button light" data-page="${page+1}" ${page===pages?'disabled':''}>Successive →</button></div>`;}
function article(id){const a=data.find(x=>x.id===decodeURIComponent(id));if(!a)return `${header()}<main id="main" class="wrap section-space"><h1>Pubblicazione non disponibile</h1><p>Il contenuto potrebbe essere ancora in bozza.</p><a class="button" href="/notizie">Torna alle notizie</a></main>${footer()}`;return `${header()}<main id="main" class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / <a href="/notizie">Pubblicazioni</a> / ${esc(categoryLabel(a.category))}</div><div class="article-layout"><article><div class="article-head"><span class="tag">${esc(categoryLabel(a.category))}</span><h1>${esc(a.title)}</h1><p class="standfirst">${esc(a.summary)}</p><div class="meta">${date(a.date)} &nbsp; · &nbsp; ${esc(a.author||'CONFAPI Roma')} &nbsp; · &nbsp; ${Math.max(1,Math.ceil(a.content.split(/\s+/).length/200))} min di lettura</div></div>${a.status!=='published'?'<p class="notice">Anteprima redazionale · Questo contenuto non è pubblicato.</p>':''}<img class="article-image" src="${esc(a.image)}" alt="Immagine del patrimonio fotografico CONFAPI"><div class="article-body">${a.richHTML||a.content.split(/\n\s*\n/).map(p=>`<p>${esc(p)}</p>`).join('')}</div><div class="article-tools"><button class="button light" data-copy>${icon('external')} Copia il link</button><button class="button light" data-print>Stampa articolo</button></div><div class="source-note">${a.needsReview?'Scheda dell’archivio precedente: estrazione da sottoporre a revisione redazionale prima della migrazione definitiva.':'Sintesi editoriale per la proposta di redesign. Le condizioni e gli allegati sono disponibili nella pubblicazione originale.'}${a.source?`<br><a href="${safeURL(a.source)}" target="_blank" rel="noopener">Consulta la fonte originale ↗</a>`:''}</div></article><aside class="article-aside"><div class="help-box"><span class="eyebrow">Dall’informazione all’azione</span><h3>Questa opportunità riguarda la tua impresa?</h3><p>Il nostro punto di partenza sono le tue esigenze. Entra in contatto con l’associazione.</p><a href="/contatti?interesse=${encodeURIComponent(a.category)}" class="button">Richiedi informazioni ${icon()}</a></div><div style="margin-top:30px"><span class="eyebrow">Continua a leggere</span>${published().filter(x=>x.category===a.category&&x.id!==a.id).slice(0,3).map(x=>`<a class="agenda-row" href="${articleLink(x)}"><h3>${esc(x.title)}</h3></a>`).join('')}</div></aside></div></main>${footer()}`;}
function services(id){const s=serviceList.find(x=>x[0]===id);return `${header('Servizi alle imprese')}<main id="main"><div class="wrap page-title"><div class="eyebrow">Servizi alle imprese</div><h1>${s?s[1]:'Un riferimento. Per ogni sfida.'}</h1><p>${s?s[2]:'Le competenze di un’associazione, la vicinanza di un interlocutore che conosce il territorio. Scegli l’area che ti interessa.'}</p></div>${s?`<div class="wrap institution"><div><h2>Affianchiamo la tua impresa.</h2><p>Il servizio ${s[1].toLowerCase()} fa parte delle aree di assistenza presenti nel sito CONFAPI Roma. La nuova esperienza mette in relazione consulenza, documenti e aggiornamenti, rendendo più semplice individuare l’interlocutore giusto.</p><div class="steps"><div class="step"><span>1</span><div><h3>Raccontaci la tua esigenza</h3><p>Condividi il tema sul quale cerchi un supporto.</p></div></div><div class="step"><span>2</span><div><h3>Individuiamo il percorso</h3><p>L’associazione valuta la richiesta e il servizio pertinente.</p></div></div><div class="step"><span>3</span><div><h3>Rimani aggiornato</h3><p>Ritrova pubblicazioni e documenti collegati all’argomento.</p></div></div></div><a class="button" href="/contatti?interesse=${encodeURIComponent(s[1])}">Parla con l’associazione ${icon()}</a></div><img src="/assets/editorial/lavoro.jpg" alt="Le competenze al servizio dell’impresa"></div>`:`<section class="soft-section section-space" style="margin-top:15px"><div class="wrap">${serviceGrid()}</div></section>`}<section class="wrap section-space"><div class="section-top"><h2>Approfondimenti e opportunità</h2><a class="text-link" href="/notizie">Vai al magazine ↗</a></div><div class="news-grid">${(s?published().filter(x=>(x.services||[]).some(link=>link.slug===id)):published()).slice(0,3).map(card).join('')}</div></section></main>${footer()}`;}
function about(){return `${header('L’associazione')}<main class="wrap about-page" id="main">
<header class="about-intro"><div class="eyebrow">L’associazione</div><h1>CONFAPI Roma e Lazio</h1><p>La nostra storia, le persone che ci rappresentano<br class="about-desktop-break"> e le regole che ci uniscono.</p></header>
<nav class="about-index" aria-label="In questa pagina"><a href="#la-storia"><span>01</span> La storia</a><a href="#il-presidente"><span>02</span> Il Presidente</a><a href="#lo-statuto-confapi"><span>03</span> Gli statuti ${icon('file')}</a></nav>
<section id="la-storia" class="about-chapter"><div class="about-chapter-label"><span>01 / La storia</span><h2>Dalla parte <br>delle imprese.</h2><div class="about-dates"><div><strong>1947</strong><span>Le origini di CONFAPI</span></div><div><strong>2017</strong><span>La ricostituzione di Roma e Lazio</span></div></div></div><div class="about-copy"><h3>Dal 1947 al servizio delle piccole e medie imprese in Italia.</h3><p>La CONFAPI è cresciuta unitamente alle piccole e medie imprese che tutela e che rappresentano il motore del nostro Paese.</p><p>La CONFAPI Roma e la CONFAPI Lazio sono state ricostituite nell’anno 2017, dopo un periodo di assenza sul territorio, e da allora hanno ristabilito un importante ruolo di rappresentanza del mondo delle PMI su tutti i tavoli istituzionali.</p><p>Insieme alle sedi territoriali, alle Unioni di Categoria e agli Enti Bilaterali, CONFAPI tutela e promuove gli interessi della piccola e media impresa e sostiene iniziative che tendono a favorire lo sviluppo economico e civile del territorio.</p><p>Ottimizza lo sviluppo delle PMI dialogando con il Governo e le parti sociali. Redige accordi con le Organizzazioni Sindacali Nazionali e stipula Contratti Collettivi Nazionali di Lavoro per le piccole e medie imprese.</p><p>Essendo l’associazione vicina alle quotidiane problematiche delle aziende, fornisce loro assistenza in modo rapido ed efficiente, facendo della tempestività il proprio punto di forza.</p></div></section>
<section id="il-presidente" class="about-chapter about-president"><span id="governance" class="about-anchor" aria-hidden="true"></span><div class="about-chapter-label"><span>02 / La governance</span><h2>Il Presidente</h2><figure><img src="/assets/images/Massimo_Tabacchiera_presidente_confapi.jpg" alt="Massimo Tabacchiera, Presidente CONFAPI Roma" loading="lazy"><figcaption>Massimo Tabacchiera</figcaption></figure></div><div class="about-copy"><h3>Massimo Tabacchiera</h3><p>Nato a Roma nel 1963, si laurea in Giurisprudenza presso la Sapienza di Roma discutendo la tesi in Penale Tributaria.</p><p>Attualmente è consigliere delegato della Siderlamina srl, società capogruppo delle aziende di famiglia, ed è Presidente del Consiglio di Amministrazione di Asteco Industria srl, azienda del gruppo di famiglia.</p><p>Dal 1992 al 1998 ricopre le cariche di Presidente Unionmeccanica Lazio e Vicepresidente di Unionmeccanica Nazionale, nonché la carica di Vicepresidente dei Giovani Imprenditori CONFAPI.</p><p>Ha ricoperto la carica di Presidente AMA spa nonché Presidente AMA International. Per sei anni, dal 2002 al 2008, ricopre la carica di Presidente di Federlazio – Associazione delle piccole e medie imprese del Lazio – e nel 2008 è Presidente ATAC Spa. Nel 2010 diventa Presidente dell’Agenzia Roma Servizi per la Mobilità srl.</p><a class="about-email" href="mailto:presidenza@confapiroma.it">${icon('mail')}<span><small>Contatta la Presidenza</small>presidenza@confapiroma.it</span>${icon()}</a></div></section>
<section id="lo-statuto-confapi" class="about-chapter about-statutes"><div class="about-chapter-label"><span>03 / Le regole comuni</span><h2>Gli statuti</h2><p>Identità, principi e funzionamento dell’associazione.</p></div><div class="about-copy"><div class="about-statute-excerpt"><span class="eyebrow">Statuto CONFAPI Roma · Articolo 1</span><blockquote>È costituita un’associazione, denominata “Associazione delle piccole e medie imprese CONFAPI di ROMA” in sigla CONFAPI ROMA, con sede in Roma. L’Associazione aderisce alla Confederazione Italiana della Piccola e Media Industria Privata – CONFAPI con sede in Roma, nei confronti della quale si obbliga ad osservare le norme statutarie e regolamentari, le deliberazioni degli organi confederali e ad adottarne il logo, nonché aderisce alla Federazione Regionale – di cui all’art. 4 dello Statuto confederale – della Regione LAZIO in conformità delle norme del corrispondente Statuto. L’Associazione, dotata di autonomia organizzativa, amministrativa e finanziaria, è costituita a tempo indeterminato, è apartitica, non ha scopo di lucro e si ispira a principi democratici.</blockquote></div><div class="about-downloads">${[['Roma','roma','208 KB'],['Lazio','lazio','267 KB']].map(([name,file,size])=>`<article class="about-document"><div class="about-document-heading">${icon('file')}<span>Documento istituzionale</span></div><h3>CONFAPI ${name}</h3><p>Atto costitutivo e statuto</p><span class="about-file-info">PDF · ${size}</span><a class="button" href="/assets/docs/atto-costitutivo_e_statuto_confapi_${file}.pdf" download>Scarica lo statuto ${icon('arrow')}</a><a class="text-link" href="/assets/docs/atto-costitutivo_e_statuto_confapi_${file}.pdf" target="_blank" rel="noopener">Apri il PDF ${icon('external')}<span class="visually-hidden"> in una nuova scheda</span></a></article>`).join('')}</div></div></section>
<section class="about-closing"><div><h2>Conosciamoci, partendo dalla tua impresa.</h2><p>La segreteria è a disposizione per informazioni sull’associazione e sui servizi.</p></div><a class="button" href="/contatti">Contatta CONFAPI ${icon()}</a></section></main>${footer()}`;}
function conventions(){return `${header('Convenzioni')}<main id="main" class="wrap"><div class="page-title"><div class="eyebrow">Il valore della rete</div><h1>Più opportunità, insieme.</h1><p>Le convenzioni presenti sul sito associativo, raccolte in uno spazio dedicato. L’associazione verifica disponibilità e condizioni applicabili.</p></div><div class="partners">${[['7Speaking','Formazione linguistica','7speaking'],['Banca del Fucino','Servizi bancari','banca-del-fucino'],['FCA Italy','Mobilità per le imprese','fca-italy-spa'],['Intesa Sanpaolo','Credito e servizi','intesa-san-paolo'],['IREDEEM','Tecnologia e acquisti','iredeem-spa'],['Fare Appalti','Gare e affidamenti','fare-appalti']].map(([name,cat,id])=>`<article class="partner"><div class="eyebrow">${cat}</div><h3>${name}</h3><p>Scopri con l’associazione i servizi della convenzione e le modalità di accesso per le imprese associate.</p><a class="text-link" href="${id==='fare-appalti'?'/notizie/fare-appalti':'/contatti?interesse='+encodeURIComponent('Convenzione '+name)}">${id==='fare-appalti'?'Scopri il servizio':'Richiedi informazioni'} ↗</a></article>`).join('')}</div></main>${footer()}`;}
function contactOffices(){return `<section class="contact-offices-v1" aria-labelledby="offices-title"><div class="offices-heading"><span class="eyebrow">Le nostre segreterie</span><h2 id="offices-title">Due riferimenti. Un filo diretto.</h2><p>Scegli la segreteria alla quale rivolgerti.</p></div><div class="offices-grid">${[['confapi','CONFAPI Roma','333 7774975','+393337774975','segreteria@confapiroma.it'],['aniem','ANIEM Lazio','334 9767911','+393349767911','segreteria@aniemlazio.it']].map(([id,name,phone,tel,email])=>`<article class="office-v1" id="sede-${id}"><div class="office-details"><span class="eyebrow">Segreteria</span><h3>${name}</h3><address>Via Giorgio Hinna 34<br>00125 Roma</address><dl><div><dt>Telefono</dt><dd><a href="tel:${tel}">${phone}</a></dd></div><div><dt>Email</dt><dd><a href="mailto:${email}">${email}</a></dd></div>${id==='confapi'?'<div><dt>PEC</dt><dd><a href="mailto:confapiroma@pec.it">confapiroma@pec.it</a></dd></div>':''}</dl></div><div class="office-map-wrap"><iframe title="Mappa della sede ${name}" src="https://www.google.com/maps?q=Via+Giorgio+Hinna+34,+00125+Roma&amp;output=embed" loading="eager" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></div><a class="office-directions" href="https://www.google.com/maps/search/?api=1&amp;query=Via+Giorgio+Hinna+34+Roma" target="_blank" rel="noopener"><span>Indicazioni stradali</span>${icon()}</a></article>`).join('')}</div></section>`;}
function membership(){if(location.pathname==='/associarsi')return membershipFull();const contact=location.pathname==='/contatti';const interest=categoryLabel(new URLSearchParams(location.search).get('interesse')||'Adesione');return `${header(contact?'Contatti':'')}<main class="wrap form-layout" id="main">${contact?contactOffices():''}<div class="form-intro"><div class="eyebrow">${contact?'Un filo diretto':'Entra in CONFAPI'}</div><h1>${contact?'La tua impresa, al centro del dialogo.':'La prossima opportunità inizia da un incontro.'}</h1><p>Raccontaci la tua impresa e i temi che ti interessano. È il primo passo per conoscere l’associazione e i suoi servizi.</p><div class="steps"><div class="step"><span>1</span><div><h3>Parliamo della tua impresa</h3><p>Condividi i riferimenti e l’area di interesse.</p></div></div><div class="step"><span>2</span><div><h3>Conosci i servizi</h3><p>Valuta il supporto più adatto alle tue esigenze.</p></div></div><div class="step"><span>3</span><div><h3>Costruiamo il percorso insieme</h3><p>Ricevi le informazioni per proseguire.</p></div></div></div><div class="documents"><a class="text-link" href="/assets/docs/Scheda-adesione-CONFAPI-ROMA.pdf" target="_blank" rel="noopener">Scarica la scheda di adesione ↗</a><a class="text-link" href="tel:+393337774975">Chiama il 333 7774975</a></div></div><form class="form-card" id="contact-form"><h2>${contact?'Come possiamo aiutarti?':'Conosciamoci.'}</h2><label class="field">Nome e cognome *<input name="name" autocomplete="name" required maxlength="100"></label><label class="field">Impresa *<input name="company" autocomplete="organization" required maxlength="150"></label><label class="field">Email di lavoro *<input name="email" type="email" autocomplete="email" required maxlength="200"></label><label class="field">Sono interessato a<select name="interest">${[...new Set([interest,'Adesione','Relazioni sindacali','Bandi e opportunità','ANIEM Lazio','Formazione','Mercati esteri'])].map(v=>`<option>${esc(v)}</option>`).join('')}</select></label><label class="field">La tua esigenza<textarea name="message" placeholder="Raccontaci brevemente di cosa hai bisogno" maxlength="2000"></textarea></label><label class="check"><input type="checkbox" name="consent" required><span>Acconsento al salvataggio dei dati inseriti in questa demo locale. Utilizzare dati di esempio. *</span></label><button type="submit" class="button" style="width:100%">Registra richiesta dimostrativa ${icon()}</button><p class="demo-note">Ambiente dimostrativo: la richiesta viene salvata nell’area redazione locale. Nessuna email viene inviata all’associazione.</p><p id="form-error" role="alert"></p></form></main>${footer()}`;}
function studio(){return `<main id="main" class="studio"><aside class="studio-sidebar"><a class="studio-brand" href="/">CONFAPI ROMA</a><div class="studio-label">STUDIO EDITORIALE</div><nav class="studio-nav" aria-label="Gestione editoriale">${[['dashboard','grid','Panoramica'],['content','file','Contenuti'],['requests','users','Richieste e imprese'],['media','book','Documenti'],['settings','shield','Il progetto']].map(([id,ic,label])=>`<button data-studio="${id}" class="${studioTab===id?'active':''}">${icon(ic)}${label}</button>`).join('')}<a class="membership-admin-link" href="/admin/adesioni">Domande di adesione firmate</a></nav><div class="studio-end"><a href="/">← Visita il sito</a>Ambiente di presentazione<br>Dati salvati su questo computer</div></aside><div class="studio-main"><div class="studio-top"><span>CONFAPI Roma e Lazio / ${editing!==null?'Editor':studioTab==='dashboard'?'Panoramica':'Gestione'}</span><span>Redazione <span class="avatar">CR</span></span></div><div id="studio-content">${editing!==null?editor():studioContent()}</div></div></main>`;}
const statuses={published:'Pubblicato',draft:'Bozza',review:'Da revisionare'};
function rows(items){return `<div class="table-wrap"><table><thead><tr><th>Contenuto</th><th>Categoria</th><th>Stato</th><th>Data</th><th><span class="visually-hidden">Azioni</span></th></tr></thead><tbody>${items.map(a=>`<tr><td><h3>${esc(a.title)}</h3><small>${esc(a.type)}${a.needsReview?' · Importazione da verificare':''}</small></td><td>${esc(categoryLabel(a.category))}</td><td><span class="status ${a.needsReview?'review':a.status}">${a.needsReview?'Da verificare':statuses[a.status]}</span></td><td style="white-space:nowrap">${a.date||'Da verificare'}</td><td><button class="row-button" data-edit="${esc(a.id)}">Modifica</button></td></tr>`).join('')}</tbody></table></div>`;}
function studioContent(){if(studioTab==='requests')return `<div class="studio-heading"><div><h1>Richieste e imprese</h1><p>Il contatto dal sito diventa un’attività da seguire.</p></div></div><div class="studio-banner">Le richieste sono quelle registrate nella demo locale. Nessuna notifica viene inviata all’esterno.</div><div class="panel">${requests.length?`<div class="table-wrap"><table><thead><tr><th>Impresa e contatto</th><th>Interesse</th><th>Richiesta</th><th>Stato</th></tr></thead><tbody>${requests.map(r=>`<tr><td><h3>${esc(r.company)}</h3>${esc(r.name)}<br><small>${esc(r.email)}</small></td><td>${esc(r.interest)}</td><td>${esc(r.message||'Richiesta di informazioni')}</td><td><select class="search-field" data-request-id="${esc(r.id)}">${['Nuova','In lavorazione','Gestita'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>Il prossimo contatto parte da qui.</h3><p>Compila il modulo del sito con dati di esempio per vedere una richiesta comparire in quest’area.</p><a class="button" href="/contatti">Apri il modulo dimostrativo</a></div>'}</div>`;
if(studioTab==='media')return `<div class="studio-heading"><div><h1>Documenti dell’associazione</h1><p>La modulistica originale, ritrovabile da un unico spazio.</p></div></div><div class="panel">${[['Scheda di adesione','Scheda-adesione-CONFAPI-ROMA.pdf'],['Statuto CONFAPI Roma','atto-costitutivo_e_statuto_confapi_roma.pdf'],['Statuto CONFAPI Lazio','atto-costitutivo_e_statuto_confapi_lazio.pdf']].map(([t,f])=>`<a class="agenda-row" href="/assets/docs/${f}" target="_blank" rel="noopener">${icon('file')}<div><h3>${t}</h3><p>Documento PDF · Apri il file originale</p></div></a>`).join('')}<p class="demo-note">Questa anteprima mostra la consultazione. Caricamento, versioni e permessi fanno parte della fase di sviluppo del CMS.</p></div>`;
if(studioTab==='settings')return `<div class="studio-heading"><h1>Un sistema costruito sul lavoro quotidiano.</h1></div><div class="panel"><h2>Un punto di partenza concreto</h2><p>Questa demo collega la pubblicazione dei contenuti, il magazine e le richieste delle imprese. Il progetto completo prevede accessi nominativi, ruoli, revisioni, gestione media e migrazione verificata.</p><p style="margin-top:20px"><a href="/analisi" class="button">Leggi analisi e progetto ${icon()}</a></p></div>`;
const drafting=data.filter(x=>x.status==='draft').length;const review=data.filter(x=>x.needsReview||x.status==='review').length;
if(studioTab==='content'){const all=data.filter(x=>(studioFilter==='all'||(studioFilter==='review'?(x.needsReview||x.status==='review'):x.status===studioFilter))&&(!query||x.title.toLowerCase().includes(query.toLowerCase())));return `<div class="studio-heading"><div><h1>Contenuti</h1><p>Articoli, bandi e circolari. Lo stesso flusso, più ordine.</p></div><button class="button" data-new>${icon('plus')} Nuovo contenuto</button></div><div class="search-row"><input class="search-field" id="studio-search" aria-label="Cerca nei contenuti" placeholder="Cerca un contenuto…" value="${esc(query)}"><select class="search-field" id="studio-status"><option value="all" ${studioFilter==='all'?'selected':''}>Tutti gli stati</option><option value="published" ${studioFilter==='published'?'selected':''}>Pubblicati</option><option value="draft" ${studioFilter==='draft'?'selected':''}>Bozze</option><option value="review" ${studioFilter==='review'?'selected':''}>Da verificare</option></select></div><div class="panel"><div class="count">${all.length} contenuti</div>${all.length?rows(all):'<div class="empty">Nessun contenuto corrisponde alla ricerca.</div>'}</div>`;}
return `<div class="studio-heading"><div><div class="eyebrow">Il tuo spazio di lavoro</div><h1>Buongiorno, Redazione.</h1><p>Le informazioni utili per organizzare la prossima pubblicazione.</p></div><button class="button" data-new>${icon('plus')} Nuovo contenuto</button></div><div class="metrics"><div class="metric"><p>Schede nel catalogo</p><strong>${data.length}</strong><small>Contenuti della demo</small></div><div class="metric"><p>Bozze in lavorazione</p><strong>${drafting}</strong><small>Pronte per essere riprese</small></div><div class="metric"><p>Da verificare</p><strong>${review}</strong><small>Revisione dell’importazione</small></div><div class="metric"><p>Richieste delle imprese</p><strong>${requests.length}</strong><small>Dal modulo dimostrativo</small></div></div><div class="studio-banner"><strong>La qualità parte dai contenuti.</strong> Le 77 schede dell’archivio precedente richiedono una verifica di testo, categoria e data prima della migrazione definitiva.</div><div class="panel"><div class="section-top"><h2>In redazione</h2><button class="row-button" data-studio="content">Tutti i contenuti →</button></div>${rows(data.filter(x=>!x.needsReview).slice(0,8))}</div><div class="panel"><h2>Dal contenuto al sito, in pochi passaggi.</h2><p>Scrivi → Salva una bozza → Controlla l’anteprima → Pubblica. Il contenuto compare nel magazine senza modificare il layout della pagina.</p></div>`;}
function editor(){const a=editing==='new'?{}:data.find(x=>x.id===editing)||{};return `<div class="studio-heading"><div><button class="row-button" data-close-editor>← Torna ai contenuti</button><h1 style="margin-top:15px">${a.id?'Modifica contenuto':'Nuovo contenuto'}</h1></div><span class="status" id="save-status">${a.id?'Salvato':'Non ancora salvato'}</span></div><form id="editor-form"><div class="editor-grid"><div class="panel"><label class="visually-hidden" for="edit-title">Titolo</label><input id="edit-title" class="editor-title" placeholder="Dai un titolo alla notizia" value="${esc(a.title)}" required minlength="3" maxlength="240"><label class="visually-hidden" for="edit-summary">Sommario</label><textarea id="edit-summary" class="editor-summary" placeholder="Il punto essenziale, in poche righe…" maxlength="600">${esc(a.summary)}</textarea><div class="editor-toolbar"><button type="button" data-insert="paragraph">Paragrafo</button><button type="button" data-insert="list">Elenco puntato</button><span style="margin-left:auto;font-size:12px;color:var(--muted);padding:8px">Testo editoriale</span></div><div id="edit-body" class="editor-body" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Testo del contenuto" data-placeholder="Scrivi qui il contenuto…">${esc(a.content)}</div></div><aside class="editor-side"><div class="panel"><h3>Pubblicazione</h3><label class="field">Stato<select id="edit-status">${[['draft','Bozza'],['review','In revisione'],['published','Pubblicato']].map(([v,n])=>`<option value="${v}" ${a.status===v?'selected':''}>${n}</option>`).join('')}</select></label><button type="submit" class="button" id="save-content">Salva contenuto ${icon()}</button><button type="button" class="button light" data-save-draft>Salva come bozza</button>${a.id?`<a href="${articleLink(a)}?preview=1" target="_blank" class="button light">Apri anteprima ↗</a>`:''}<p class="demo-note">Il salvataggio modifica soltanto questa demo. Se scegli “Pubblicato”, il contenuto sarà visibile nel magazine locale.</p><p id="editor-error" role="alert" style="font-size:13px;color:#9b3131"></p></div><div class="panel"><h3>Organizzazione</h3><label class="field">Categoria<select id="edit-category">${categories.slice(1).map(c=>`<option ${a.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Tipo di contenuto<select id="edit-type">${['Articolo','Circolare','Bando','Notiziario','Progetto','Servizio'].map(t=>`<option ${a.type===t?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="panel"><h3>Immagine di copertina</h3><img src="${esc(a.image||'/assets/editorial/industria.jpg')}" alt="Anteprima della copertina" style="height:100px;width:100%;object-fit:cover"><p class="demo-note">Immagine del patrimonio CONFAPI. Gestione caricamenti prevista nel CMS definitivo.</p></div></aside></div></form>`;}
function notify(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function refreshData(studioMode=false){const r=await fetch('/api/demo/articles'+(studioMode?'?studio=1':''));if(!r.ok)throw Error('Contenuti non disponibili');data=(await r.json()).map(a=>({...a,category:categoryLabel(a.category)}));const servicesResponse=await fetch('/api/demo/services');if(servicesResponse.ok){const icons=Object.fromEntries(serviceList.map(s=>[s[0],s[3]]));serviceList=(await servicesResponse.json()).map(s=>[s.slug,esc(s.name),esc(s.summary),icons[s.slug]||'work']);}if(studioMode){const p=await fetch('/api/demo/requests');requests=p.ok?await p.json():[];}if(location.pathname==='/analisi'&&!window.auditMarkup){window.auditMarkup=await(await fetch('/audit-content.html')).text();}}
function render(){const path=location.pathname;let html;if(path==='/studio')html=studio();else if(path==='/sistema-confapi'||path.startsWith('/sistema-confapi/'))html=systemPage(path.split('/')[2]);else if(path==='/aniem')html=aniemPage();else if(path==='/notizie')html=news();else if(path.startsWith('/notizie/'))html=article(path.split('/').pop());else if(path.startsWith('/servizi'))html=services(path.split('/')[2]);else if(path==='/chi-siamo')html=about();else if(path==='/convenzioni')html=conventions();else if(['/associarsi','/contatti'].includes(path))html=membership();else if(path==='/analisi')html=header()+`<main id="main" class="wrap audit">${window.auditMarkup||''}</main>`+footer();else html=home();$('#app').innerHTML=html;if(path==='/associarsi'){window.membershipToast=notify;window.initMembership();}if(path==='/notizie')renderArchive();document.title=path==='/studio'?'Studio editoriale · CONFAPI Roma':($('#main h1')?.textContent||'CONFAPI Roma')+' · CONFAPI Roma';}
async function navigate(url){history.pushState({},'',url);filter='Tutti';query='';editing=null;await refreshData(location.pathname==='/studio'||location.search.includes('preview=1'));render();window.scrollTo(0,0);if(location.search.includes('ricerca=1'))$('#news-search')?.focus();}
document.addEventListener('click',async e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&!a.target&&!a.hasAttribute('download')&&!a.pathname.startsWith('/admin')&&!a.pathname.startsWith('/privacy')&&!a.pathname.startsWith('/assets/')&&!a.pathname.endsWith('.html')&&!e.ctrlKey&&!e.metaKey&&!a.hash){e.preventDefault();try{await navigate(a.pathname+a.search);}catch(err){notify('Impossibile aprire la pagina. Verifica che il server sia attivo.');}return;}
const b=e.target.closest('button');if(!b)return;
if(b.dataset.homeFilter){filter=b.dataset.homeFilter;document.querySelectorAll('[data-home-filter]').forEach(x=>x.classList.toggle('active',x===b));$('#home-news').innerHTML=homeCards();}
if(b.dataset.newsFilter){filter=b.dataset.newsFilter;page=1;document.querySelectorAll('[data-news-filter]').forEach(x=>x.classList.toggle('active',x===b));renderArchive();}
if(b.dataset.page){page=Number(b.dataset.page);renderArchive();$('#news-search').scrollIntoView({block:'start'});}
if(b.hasAttribute('data-reset-search')){filter='Tutti';query='';$('#news-search').value='';document.querySelectorAll('[data-news-filter]').forEach(x=>x.classList.toggle('active',x.dataset.newsFilter==='Tutti'));renderArchive();}
if(b.dataset.studio){studioTab=b.dataset.studio;editing=null;query='';render();}
if(b.hasAttribute('data-new')){editing='new';render();$('#edit-title').focus();}
if(b.dataset.edit){editing=b.dataset.edit;render();}
if(b.hasAttribute('data-close-editor')){editing=null;studioTab='content';render();}
if(b.hasAttribute('data-copy')){try{await navigator.clipboard.writeText(location.href);notify('Link copiato negli appunti');}catch{notify('Puoi copiare il link dalla barra degli indirizzi.');}}
if(b.hasAttribute('data-print'))window.print();
if(b.hasAttribute('data-save-draft')){$('#edit-status').value='draft';$('#editor-form').requestSubmit();}
if(b.dataset.insert){$('#edit-body').focus();document.execCommand('insertText',false,b.dataset.insert==='list'?'\n• ':'\n\n');}
});
document.addEventListener('input',e=>{if(e.target.id==='news-search'){query=e.target.value;page=1;renderArchive();}if(e.target.id==='studio-search'){query=e.target.value;const pos=e.target.selectionStart;$('#studio-content').innerHTML=studioContent();$('#studio-search').focus();$('#studio-search').setSelectionRange(pos,pos);}if(e.target.closest('#editor-form')&&$('#save-status'))$('#save-status').textContent='Modifiche non salvate';});
document.addEventListener('change',async e=>{if(e.target.id==='news-sort')renderArchive();if(e.target.id==='studio-status'){studioFilter=e.target.value;$('#studio-content').innerHTML=studioContent();}if(e.target.dataset.requestId){try{const r=await fetch('/api/demo/requests/'+e.target.dataset.requestId,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:e.target.value})});if(!r.ok)throw Error();requests=await (await fetch('/api/demo/requests')).json();notify('Stato della richiesta aggiornato');}catch{notify('Salvataggio non riuscito');}}});
document.addEventListener('submit',async e=>{if(e.target.id==='contact-form'){e.preventDefault();const f=new FormData(e.target);const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{const res=await fetch('/api/demo/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.get('name'),company:f.get('company'),email:f.get('email'),interest:f.get('interest'),message:e.target.dataset.membership?['Partita IVA / CF: '+f.get('vat'),'Sede legale: '+f.get('address'),'Comune e CAP: '+f.get('city'),'Telefono: '+f.get('phone'),'PEC: '+f.get('pec'),'Dipendenti: '+f.get('employees'),'Settore / CCNL: '+f.get('sector'),f.get('message')||''].join('\n'):f.get('message'),consent:f.get('consent')==='on'})});const j=await res.json();if(!res.ok)throw Error(j.error);e.target.innerHTML='<div class="success"><span class="tag">Richiesta registrata nella demo</span><h2>Il contatto è ora in redazione.</h2><p>Apri l’area di gestione per vedere la richiesta e seguirne lo stato.</p><a href="/admin" class="button" style="margin-top:25px">Vai all’area redazione →</a></div>';studioTab='requests';}catch(err){$('#form-error').textContent=err.message;button.disabled=false;}}
if(e.target.id==='editor-form'){e.preventDefault();const btn=$('#save-content');btn.disabled=true;const payload={id:editing==='new'?undefined:editing,title:$('#edit-title').value,summary:$('#edit-summary').value,content:$('#edit-body').innerText,category:$('#edit-category').value,type:$('#edit-type').value,status:$('#edit-status').value};try{const r=await fetch('/api/demo/articles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const j=await r.json();if(!r.ok)throw Error(j.error);editing=j.id;await refreshData(true);render();notify(j.status==='published'?'Contenuto pubblicato nel magazine locale':'Contenuto salvato');}catch(err){$('#editor-error').textContent=err.message;btn.disabled=false;}}
});
window.addEventListener('popstate',async()=>{await refreshData(location.pathname==='/studio'||location.search.includes('preview=1'));render();});
refreshData(location.pathname==='/studio'||location.search.includes('preview=1')).then(render).catch(()=>{$('#app').innerHTML='<main class="wrap section-space"><h1>Il magazine sta per arrivare.</h1><p>Il server locale non risponde. Ricarica la pagina quando è attivo.</p><button class="button" onclick="location.reload()">Riprova</button></main>';});
document.addEventListener('click',e=>{
 const toggle=e.target.closest('.menu-toggle');
 if(toggle){const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.querySelector('span').textContent=open?'Chiudi':'Menu';return;}
 if(!e.target.closest('.nav'))closeMobileMenu();
});
function closeMobileMenu(){const toggle=document.querySelector('.menu-toggle');if(toggle){toggle.setAttribute('aria-expanded','false');toggle.querySelector('span').textContent='Menu';}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const toggle=document.querySelector('.menu-toggle[aria-expanded="true"]');if(toggle){closeMobileMenu();toggle.focus();}}});
const networkPartners=[["pmi_welfare_manager.png","PMI Welfare Manager","Fondo Solidarietà Manager PMI","http://www.pmiwfm.it/"],["cespim.png","CESPIM","Centro Sviluppo PMI","http://www.cespim.com/"],["confapi_servizi.png","CONFAPI SERVIZI","Relazioni Industriali & Sindacali","http://www.confapi.org/it/i-servizi/relazioni-industriali-e-sindacali.html"],["ebm.png","E.B.M.","Ente Bilaterale Metalmeccanici","http://www.entebilateralemetalmeccanici.it/index.jsp"],["enfea.png","ENFEA","Ente Bilaterale Nazionale PMI","http://www.enfea.it/index.jsp"],["fapi.png","FAPI","Fondo Formazione PMI","https://www.fondopmi.com/"],["fasdapi.png","FASDAPI","Fondo Assistenza Sanitaria Dirigenti","http://www.fasdapi.it/"],["fincredit.png","FINCREDIT","Confidi & Credito Confapi","https://www.fincreditconfapi.it/"],["fondapi.png","FONDAPI","Fondo Pensione Complementare PMI","http://www.fondapi.it/"],["fondazione_idi.png","FONDAZIONE IDI","Istituto Dirigenti Italiani","http://www.fondazioneidi.it/web/guest"],["fondo_dirigenti_pmi.png","FONDO DIRIGENTI PMI","Finanziamento Formazione Dirigenti","http://crm.fondodirigentipmi.it/"],["previndapi.png","PREVINDAPI","Fondo Pensione Quadri & Dirigenti","http://www.previndapi.it/"]];
function networkSection(){return `<section class="network-section"><div class="network-heading"><div class="eyebrow">Il sistema CONFAPI</div><h2>Una rete di competenze.<br>Al servizio delle imprese.</h2><p>Enti bilaterali, fondi e società del sistema: formazione, welfare, previdenza e sostegno alle PMI. Scopri i singoli enti nei rispettivi portali.</p></div><div class="network-grid">${networkPartners.map(([img,name,desc,url])=>`<a class="network-card" href="${esc(url)}" target="_blank" rel="noopener noreferrer"><img src="/assets/logos/${img}" alt="" loading="lazy"><strong>${esc(name)}</strong><span>${esc(desc)}</span><span class="network-external" aria-label="Apri il portale in una nuova scheda">${icon('external')}</span></a>`).join('')}</div></section>`;}
function aniemPage(){
 const articles=published().filter(a=>a.category==='ANIEM Lazio'&&!/^(archivio\s+)?news(\s+edilizia)?\s+aniem$/i.test(a.title.trim())).sort((a,b)=>Number(b.featured)-Number(a.featured)||(b.date||'').localeCompare(a.date||''));
 const latest=articles[0], pages=Math.max(1,Math.ceil(Math.max(0,articles.length-1)/9));
 const current=Math.min(pages,Math.max(1,Number(new URLSearchParams(location.search).get('pagina'))||1));
 return `${header('News Aniem')}<main id="main" class="wrap aniem-page"><div class="aniem-page-intro"><div><div class="eyebrow">Notizie e pubblicazioni</div><h1>ANIEM Lazio</h1><p>Il punto su edilizia, appalti e territorio. Notiziari e aggiornamenti per seguire da vicino il mondo delle imprese edili.</p></div><a class="text-link" href="#pubblicazioni-aniem">Sfoglia le pubblicazioni ${icon()}</a></div>${latest?`<section class="aniem-latest" aria-label="Ultima pubblicazione"><a href="${articleLink(latest)}"><img src="${esc(latest.image)}" alt=""></a><div><span class="eyebrow">L’ultima pubblicazione · ${shortDate(latest.date)}</span><h2><a href="${articleLink(latest)}">${esc(latest.title)}</a></h2><p>${esc(latest.summary)}</p><a class="button" href="${articleLink(latest)}">Leggi la pubblicazione ${icon()}</a></div></section>`:''}<section id="pubblicazioni-aniem" class="section-space"><div class="section-top"><h2>Le pubblicazioni ANIEM Lazio</h2><span class="meta">${articles.length} pubblicazioni</span></div><div class="news-grid">${articles.slice(1+(current-1)*9,1+current*9).map(card).join('')||'<p>Le prossime pubblicazioni saranno disponibili qui.</p>'}</div>${pages>1?`<nav class="pagination" aria-label="Pagine pubblicazioni ANIEM">${current>1?`<a class="button light" href="/aniem?pagina=${current-1}">Precedenti</a>`:''}<span>${current} / ${pages}</span>${current<pages?`<a class="button light" href="/aniem?pagina=${current+1}">Successive</a>`:''}</nav>`:''}</section></main>${footer()}`;
}
document.addEventListener('click',e=>{
 const service=e.target.closest('.services-toggle');
 if(service){const opening=service.getAttribute('aria-expanded')!=='true';closeServices();service.setAttribute('aria-expanded',String(opening));service.closest('.services-nav').classList.toggle('is-open',opening);}
 else if(!e.target.closest('.services-nav'))closeServices();
});
function closeServices(){document.querySelectorAll('.services-nav').forEach(n=>{n.classList.remove('is-open');n.querySelector('button').setAttribute('aria-expanded','false');});}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const current=document.activeElement?.closest('.services-nav.is-open');current?.querySelector('button').focus();closeServices();}});
document.addEventListener('pointerover',e=>{const n=e.target.closest('.services-nav');if(n&&!n.contains(e.relatedTarget)&&matchMedia('(hover:hover) and (min-width:1151px)').matches){closeServices();n.classList.add('is-open');n.querySelector('button').setAttribute('aria-expanded','true');}});
document.addEventListener('pointerout',e=>{const n=e.target.closest('.services-nav');if(n&&!n.contains(e.relatedTarget)&&!n.contains(document.activeElement)&&matchMedia('(hover:hover) and (min-width:1151px)').matches){n.classList.remove('is-open');n.querySelector('button').setAttribute('aria-expanded','false');}});
document.addEventListener('focusout',e=>{const n=e.target.closest('.services-nav');if(n&&!n.contains(e.relatedTarget)){n.classList.remove('is-open');n.querySelector('button').setAttribute('aria-expanded','false');}});
setInterval(()=>{
 const ticker=document.querySelector('.news-ticker'),view=ticker?.querySelector('.ticker-window');
 if(!view||matchMedia('(prefers-reduced-motion: reduce)').matches||ticker.matches(':hover')||ticker.contains(document.activeElement))return;
 if(view.scrollLeft+view.clientWidth>=view.scrollWidth-1)view.scrollLeft=0;else view.scrollLeft+=1;
},45);
let tiltedNetworkCard=null,networkTiltFrame=0;
const networkMotionAllowed=()=>matchMedia('(hover: hover) and (pointer: fine)').matches&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
function resetNetworkTilt(){if(tiltedNetworkCard){tiltedNetworkCard.style.removeProperty('--tilt-x');tiltedNetworkCard.style.removeProperty('--tilt-y');tiltedNetworkCard.classList.remove('is-tilted');tiltedNetworkCard=null;}cancelAnimationFrame(networkTiltFrame);}
document.addEventListener('pointermove',e=>{
 const card=e.target.closest('.network-card');
 if(!card||!networkMotionAllowed()){resetNetworkTilt();return;}
 if(tiltedNetworkCard!==card){resetNetworkTilt();tiltedNetworkCard=card;}
 const rect=card.getBoundingClientRect(),x=Math.max(-1,Math.min(1,(e.clientX-rect.left)/rect.width*2-1)),y=Math.max(-1,Math.min(1,(e.clientY-rect.top)/rect.height*2-1));
 cancelAnimationFrame(networkTiltFrame);
 networkTiltFrame=requestAnimationFrame(()=>{if(tiltedNetworkCard!==card)return;card.style.setProperty('--tilt-x',(-y*3).toFixed(2)+'deg');card.style.setProperty('--tilt-y',(x*3).toFixed(2)+'deg');card.classList.add('is-tilted');});
});
document.addEventListener('pointerout',e=>{if(tiltedNetworkCard&&!tiltedNetworkCard.contains(e.relatedTarget))resetNetworkTilt();});
window.addEventListener('blur',resetNetworkTilt);
document.addEventListener('scroll',resetNetworkTilt,{passive:true});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',resetNetworkTilt);
function membershipFull(){return header()+window.membershipMarkup(esc,icon)+footer();}
